    "code": "'use client';\n\nimport { Card } from 'ui-lab-components/card';\nimport { Page } from 'ui-lab-components/page';\nimport { Skeleton } from 'ui-lab-components/skeleton';\nimport { Header } from './layout/Header';\n\nexport function ApplicationHeader() {\n  return (\n    <Page padding=\"none\" gap=\"none\">\n      <Header />\n\n      <main className=\"space-y-8 px-4 py-10 sm:px-6\">\n        <section\n          aria-busy=\"true\"\n          aria-label=\"Loading dashboard\"\n          className=\"space-y-8\"\n        >\n          <div className=\"space-y-3\">\n            <Skeleton.Text size=\"heading\" w={220} color=\"background-800\" />\n            <Skeleton.Text lines={1} w={320} color=\"background-800\" />\n          </div>\n\n          <div className=\"grid gap-4 sm:grid-cols-3\">\n            {[0, 1, 2].map((i) => (\n              <Card key={i}>\n                <Card.Body className=\"space-y-4 p-5\">\n                  <Skeleton.Text lines={1} w={96} color=\"background-800\" />\n                  <Skeleton w={120} h={28} color=\"background-800\" />\n                  <Skeleton.Text lines={1} w=\"60%\" color=\"background-800\" />\n                </Card.Body>\n              </Card>\n            ))}\n          </div>\n\n          <Card>\n            <Card.Body className=\"space-y-5 p-6\">\n              <Skeleton.Image ratio=\"16/9\" color=\"background-800\" />\n              <Skeleton.Text lines={4} lastLineWidth=\"70%\" color=\"background-800\" />\n            </Card.Body>\n          </Card>\n        </section>\n      </main>\n    </Page>\n  );\n}\n",
