    "code": "'use client';\n\nimport { Progress } from 'ui-lab-components/progress';\n\nfunction UsageProgress({ label, value, max = 100 }: { label: string; value: number; max?: number }) {\n  const percentage = Math.round((value / max) * 100);\n  const variant = percentage >= 90 ? 'error' : percentage >= 75 ? 'warning' : 'success';\n  return <Progress label={label} value={value} max={max} showValue variant={variant} />;\n}\n\nexport function ProgressMetricColoredDemo() {\n  return <UsageProgress label=\"Storage used\" value={86} />;\n}\n",
